package com.bank.trade.model;

import jakarta.persistence.*;

@Entity
@Table(name = "trades")
public class Trade {
    @Id
    private String tradeId;
    private String symbol;
    private int quantity;
    private String status = "CAPTURED";

    protected Trade() { }
    public Trade(String tradeId, String symbol, int quantity) {
        this.tradeId = tradeId; this.symbol = symbol; this.quantity = quantity;
    }
    public String getTradeId() { return tradeId; }
}
