package com.bank.trade.service;

import com.bank.trade.model.Trade;
import com.bank.trade.repository.TradeRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class TradeService {

    private final TradeRepository tradeRepo;

    // Normal path: let Hibernate buffer and flush at commit (best for throughput)
    @Transactional
    public void captureBatch(List<Trade> trades) {
        for (Trade t : trades) {
            tradeRepo.save(t);  // managed + INSERT queued, no SQL yet
        }
        log.info("Buffered {} trades; SQL flushes at commit", trades.size());
    }

    // Immediate path: force the INSERT now so a duplicate-id error surfaces here
    @Transactional
    public void captureImmediate(Trade t) {
        tradeRepo.saveAndFlush(t);  // INSERT runs NOW — unique violation shows here
        log.info("Trade {} flushed immediately", t.getTradeId());
    }

    // Must-flush path: a native query in the same TX needs to see the new row
    @Transactional
    public List<String> captureThenReconcile(Trade t) {
        tradeRepo.saveAndFlush(t);           // flush so native SQL sees the row
        return tradeRepo.findCapturedIdsNative();
    }
}
